#!/usr/bin/env python3
"""Generate db/main SQL (outbox table and statement-level triggers) from config.yaml."""
import os, yaml

def generate_sql():
    with open("config.yaml", "r", encoding="utf-8") as f:
        cfg = yaml.safe_load(f)

    excluded = cfg["business_rules"]["excluded_statuses"]
    excl_sql = ", ".join(f"'{s}'" for s in excluded)

    sql = f"""-- Auto-generated from config.yaml. DO NOT EDIT DIRECTLY.
-- Generated by scripts/generate_triggers.py

CREATE TABLE IF NOT EXISTS outbox (
    id bigserial PRIMARY KEY,
    xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
    kind text NOT NULL,
    tenant_id int NOT NULL,
    bucket_ts timestamp NOT NULL,
    status text,
    product_id bigint,
    category text,
    delta_count int NOT NULL DEFAULT 0,
    delta_amount numeric(14,2) NOT NULL DEFAULT 0.00,
    created_at timestamp NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX IF NOT EXISTS outbox_xid_id_idx ON outbox (xid, id);

--------------------------------------------------------------------------------
-- 1. Orders Statement-Level Triggers
--------------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION trg_orders_insert_stmt()
RETURNS trigger AS $$
BEGIN
    INSERT INTO outbox (kind, tenant_id, bucket_ts, status, delta_count, delta_amount)
    SELECT
        'order',
        n.tenant_id,
        date_trunc('hour', n.created_at),
        n.status,
        1,
        CASE WHEN n.status NOT IN ({excl_sql}) THEN n.total ELSE 0.00 END
    FROM new_table n;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trg_orders_delete_stmt()
RETURNS trigger AS $$
BEGIN
    INSERT INTO outbox (kind, tenant_id, bucket_ts, status, delta_count, delta_amount)
    SELECT
        'order',
        o.tenant_id,
        date_trunc('hour', o.created_at),
        o.status,
        -1,
        CASE WHEN o.status NOT IN ({excl_sql}) THEN -o.total ELSE 0.00 END
    FROM old_table o;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trg_orders_update_stmt()
RETURNS trigger AS $$
BEGIN
    -- 1. If bucket moved (status or hour changed), emit -1 for old bucket and +1 for new bucket
    INSERT INTO outbox (kind, tenant_id, bucket_ts, status, delta_count, delta_amount)
    SELECT
        'order',
        o.tenant_id,
        date_trunc('hour', o.created_at),
        o.status,
        -1,
        CASE WHEN o.status NOT IN ({excl_sql}) THEN -o.total ELSE 0.00 END
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    WHERE o.status IS DISTINCT FROM n.status
       OR date_trunc('hour', o.created_at) IS DISTINCT FROM date_trunc('hour', n.created_at);

    INSERT INTO outbox (kind, tenant_id, bucket_ts, status, delta_count, delta_amount)
    SELECT
        'order',
        n.tenant_id,
        date_trunc('hour', n.created_at),
        n.status,
        1,
        CASE WHEN n.status NOT IN ({excl_sql}) THEN n.total ELSE 0.00 END
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    WHERE o.status IS DISTINCT FROM n.status
       OR date_trunc('hour', o.created_at) IS DISTINCT FROM date_trunc('hour', n.created_at);

    -- 2. If bucket remained identical, but total changed: fold -1/+1 pair into single net delta row
    INSERT INTO outbox (kind, tenant_id, bucket_ts, status, delta_count, delta_amount)
    SELECT
        'order',
        n.tenant_id,
        date_trunc('hour', n.created_at),
        n.status,
        0,
        CASE WHEN n.status NOT IN ({excl_sql}) THEN (n.total - o.total) ELSE 0.00 END
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    WHERE o.status IS NOT DISTINCT FROM n.status
      AND date_trunc('hour', o.created_at) IS NOT DISTINCT FROM date_trunc('hour', n.created_at)
      AND o.total IS DISTINCT FROM n.total;

    -- FAN OUT: If order changed from counted -> excluded (e.g. canceled), subtract all its items
    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        i.tenant_id,
        date_trunc('day', o.created_at),
        i.product_id,
        p.category,
        -i.qty,
        -(i.qty * i.price)
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    JOIN order_items i ON i.order_id = o.order_id
    JOIN products p ON p.product_id = i.product_id
    WHERE o.status NOT IN ({excl_sql})
      AND n.status IN ({excl_sql});

    -- FAN OUT: If order changed from excluded -> counted, add all its items
    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        i.tenant_id,
        date_trunc('day', n.created_at),
        i.product_id,
        p.category,
        i.qty,
        (i.qty * i.price)
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    JOIN order_items i ON i.order_id = n.order_id
    JOIN products p ON p.product_id = i.product_id
    WHERE o.status IN ({excl_sql})
      AND n.status NOT IN ({excl_sql});

    -- If day changed on a counted order, shift items to the new day
    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        i.tenant_id,
        date_trunc('day', o.created_at),
        i.product_id,
        p.category,
        -i.qty,
        -(i.qty * i.price)
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    JOIN order_items i ON i.order_id = o.order_id
    JOIN products p ON p.product_id = i.product_id
    WHERE o.status NOT IN ({excl_sql})
      AND n.status NOT IN ({excl_sql})
      AND date_trunc('day', o.created_at) IS DISTINCT FROM date_trunc('day', n.created_at);

    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        i.tenant_id,
        date_trunc('day', n.created_at),
        i.product_id,
        p.category,
        i.qty,
        (i.qty * i.price)
    FROM old_table o
    JOIN new_table n ON o.order_id = n.order_id
    JOIN order_items i ON i.order_id = n.order_id
    JOIN products p ON p.product_id = i.product_id
    WHERE o.status NOT IN ({excl_sql})
      AND n.status NOT IN ({excl_sql})
      AND date_trunc('day', o.created_at) IS DISTINCT FROM date_trunc('day', n.created_at);

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

--------------------------------------------------------------------------------
-- 2. Order Items Statement-Level Triggers
--------------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION trg_order_items_insert_stmt()
RETURNS trigger AS $$
BEGIN
    -- Only emit item fact rows if parent order is counted
    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        n.tenant_id,
        date_trunc('day', o.created_at),
        n.product_id,
        p.category,
        n.qty,
        (n.qty * n.price)
    FROM new_table n
    JOIN orders o ON o.order_id = n.order_id
    JOIN products p ON p.product_id = n.product_id
    WHERE o.status NOT IN ({excl_sql});
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION trg_order_items_delete_stmt()
RETURNS trigger AS $$
BEGIN
    INSERT INTO outbox (kind, tenant_id, bucket_ts, product_id, category, delta_count, delta_amount)
    SELECT
        'item',
        o.tenant_id,
        date_trunc('day', ord.created_at),
        o.product_id,
        p.category,
        -o.qty,
        -(o.qty * o.price)
    FROM old_table o
    JOIN orders ord ON ord.order_id = o.order_id
    JOIN products p ON p.product_id = o.product_id
    WHERE ord.status NOT IN ({excl_sql});
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

--------------------------------------------------------------------------------
-- 3. Bind Statement-Level Triggers with Transition Tables
--------------------------------------------------------------------------------

DROP TRIGGER IF EXISTS trg_orders_insert ON orders;
CREATE TRIGGER trg_orders_insert
AFTER INSERT ON orders
REFERENCING NEW TABLE AS new_table
FOR EACH STATEMENT EXECUTE FUNCTION trg_orders_insert_stmt();

DROP TRIGGER IF EXISTS trg_orders_delete ON orders;
CREATE TRIGGER trg_orders_delete
AFTER DELETE ON orders
REFERENCING OLD TABLE AS old_table
FOR EACH STATEMENT EXECUTE FUNCTION trg_orders_delete_stmt();

DROP TRIGGER IF EXISTS trg_orders_update ON orders;
CREATE TRIGGER trg_orders_update
AFTER UPDATE ON orders
REFERENCING OLD TABLE AS old_table NEW TABLE AS new_table
FOR EACH STATEMENT EXECUTE FUNCTION trg_orders_update_stmt();

DROP TRIGGER IF EXISTS trg_order_items_insert ON order_items;
CREATE TRIGGER trg_order_items_insert
AFTER INSERT ON order_items
REFERENCING NEW TABLE AS new_table
FOR EACH STATEMENT EXECUTE FUNCTION trg_order_items_insert_stmt();

DROP TRIGGER IF EXISTS trg_order_items_delete ON order_items;
CREATE TRIGGER trg_order_items_delete
AFTER DELETE ON order_items
REFERENCING OLD TABLE AS old_table
FOR EACH STATEMENT EXECUTE FUNCTION trg_order_items_delete_stmt();
"""
    os.makedirs("db/main", exist_ok=True)
    out_file = "db/main/triggers.sql"
    with open(out_file, "w", encoding="utf-8") as f:
        f.write(sql)
    print(f"Generated {out_file}")
    return sql

if __name__ == "__main__":
    generate_sql()
